import json,re,collections
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text()); r=json.loads(Path('reference-targets.json').read_text())
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
class ValidateHTML(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.stack=[]
 def handle_starttag(self,tag,attrs):
  assert tag in allowed,tag
  for k,v in attrs: assert k in ['rowspan','colspan'] and v.isdigit(),(tag,k,v)
  if tag"'!='"'br':self.stack.append(tag)
 def handle_endtag(self,tag):
  assert self.stack and self.stack.pop()==tag,(tag,self.stack)
 def handle_startendtag(self,tag,attrs):
  self.handle_starttag(tag,attrs)
  if tag"'!='"'br':self.handle_endtag(tag)
def txt(xml):return unescape(re.sub(r'<["'^>]*>'"', '',xml or ''))
assert len(a)==len(s)==24
for old,new in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert old[k]==new[k],(k,new['number'])
 assert new['status'] in ['retained_unchanged','rewrite_draft']
 if new['status']=='retained_unchanged':
  assert new['proposed_xml'] is None and new['classification']=='retained_necessary'
  assert new['substantive_impact']['classification']=='retained_necessary' and new['substantive_impact']['effects']==[]
 else:
  p=ValidateHTML();p.feed(new['proposed_xml']);assert not p.stack,(new['number'],p.stack)
 if old.get('benefit_check_required'): assert len(new['benefit_review'])>=100
 imp=new['substantive_impact'];assert imp['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(imp[k])>=40
 for e in imp['effects']:
  assert re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  assert len(e['source_quote'])>=12 and e['source_quote'] in txt(old['source_xml'])
  assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in txt(new['proposed_xml'])
 key=old['code_id']+'|'+old['source_id']; required=r['requirements'][key]
 assert [c['target_key'] for c in new['reference_checks']]==required
 for c in new['reference_checks']:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
 if new.get('change_type')=='full_repeal':
  assert txt(new['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
  assert new['repeal_policy_id']=='editorial_direction_2026_10_19' and len(new['repeal_scope'])>=30
 if new.get('change_type')=='normative_reduction':
  assert new['reform_policy_id']=='editorial_direction_2026_10_19'
  assert new['removed_provisions'] and all(len(x)>=30 for x in new['removed_provisions'])
print('Structure JSON, identifiants, XML, citations, métadonnées et 22 vérifications de renvois : conformes aux contrôles matériels.')
print('Statuts :',dict(collections.Counter(x['status'] for x in a)))
print('Impacts :',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('Changements :',dict(collections.Counter(x.get('change_type','sans-exception') for x in a)))
print('Articles rédigés :',', '.join(x['number'] for x in a if x['proposed_xml']))
for old,new in zip(s,a):
 if new['proposed_xml']:
  bnum=re.findall(r'\\d+(?:[,.]\\d+)?',txt(old['source_xml']));anum=re.findall(r'\\d+(?:[,.]\\d+)?',txt(new['proposed_xml']))
  print(new['number'],'chiffres source',bnum,'proposition',anum)
